     long     nat_hw_a_issue_cycle = -1, nat_hw_a_done_cycle = -1;

+#ifdef ACTUAL_DMA_SYSTEM
+    // ---- §42 pause/drain state (test-only, system build) ---------------
+    uint32_t pause_mode   = 0;      // 0=off, 1=mode1, 2=mode2
+    uint32_t pause_offers = 4;
+    uint32_t pause_window = 10000;
+    bool     pause_triggered = false;
+    bool     pause_active    = false;
+    bool     pause_sealed    = false;
+    bool     pause_quiet_seen = false;
+    bool     pause_a_offers_grew_after_seal = false;
+    bool     pause_children_grew_after_quiet = false;
+    long     pause_request_cycle = -1;
+    long     pause_seal_cycle = -1;
+    long     pause_first_quiet_cycle = -1;
+    long     pause_end_cycle = -1;
+    uint32_t pause_active_cycles = 0;
+    uint32_t pause_sealed_offers = 0;
+    uint32_t pause_quiet_children = 0;
+
+    struct PauseSnap {
+        uint32_t offers = 0, wlast = 0, pendb = 0, children = 0, parents = 0;
+        uint64_t childbytes = 0, end = 0, rbytes = 0, wbytes = 0;
+        uint64_t v_rbytes = 0, v_wbytes = 0;
+        bool held = false, readbusy = false, preparebusy = false, quiet = false;
+        bool a_done = false;
+        long cycle = 0;
+    };
+    PauseSnap pause_req_snap, pause_seal_snap, pause_quiet_snap, pause_end_snap, pause_term_snap;
+
+    void pause_capture(PauseSnap& s) {
+        s.offers      = (uint32_t)top->dbg_pause_a_offers;
+        s.wlast       = (uint32_t)top->dbg_pause_a_wlast;
+        s.pendb       = (uint32_t)top->dbg_pause_a_bpending;
+        s.children    = (uint32_t)top->dbg_pause_a_children;
+        s.parents     = (uint32_t)top->dbg_pause_a_parents;
+        s.childbytes  = top->dbg_pause_a_childbytes;
+        s.end         = top->dbg_pause_a_end;
+        s.rbytes      = top->dbg_pause_a_rbytes;
+        s.wbytes      = top->dbg_pause_a_wbytes;
+        s.v_rbytes    = top->dbg_pause_v_rbytes;
+        s.v_wbytes    = top->dbg_pause_v_wbytes;
+        s.held        = top->dbg_pause_a_held;
+        s.readbusy    = top->dbg_pause_a_read_busy;
+        s.preparebusy = top->dbg_pause_a_prepare_busy;
+        s.quiet       = top->dbg_pause_a_quiet;
+        s.a_done      = (n_nat_hw_a_done >= 1);
+        s.cycle       = g_cycle;
+    }
+
+    void pause_emit(const char* phase, const PauseSnap& s, bool full_accepted = false) {
+        std::printf("PAUSE42-JSON {"
+            "\"schema\":\"pause42-v1\","
+            "\"phase\":\"%s\","
+            "\"mode\":%u,"
+            "\"first\":\"%s\","
+            "\"g_cycle\":%ld,"
+            "\"request_cycle\":%ld,"
+            "\"seal_cycle\":%ld,"
+            "\"first_quiet_cycle\":%ld,"
+            "\"end_cycle\":%ld,"
+            "\"cycles_since_request\":%ld,"
+            "\"Aoffers\":%u,\"wlast\":%u,\"pendb\":%u,"
+            "\"children\":%u,\"childbytes\":%llu,\"parents\":%u,"
+            "\"end\":%llu,\"rbytes\":%llu,\"wbytes\":%llu,"
+            "\"held\":%d,\"readbusy\":%d,\"preparebusy\":%d,\"quiet\":%d,"
+            "\"V_rbytes\":%llu,\"V_wbytes\":%llu,"
+            "\"a_job_done\":%d,"
+            "\"tl_accept\":%llu,\"tl_resp\":%llu,"
+            "\"ptw_active\":%llu,\"iotlb_lookup\":%llu,\"iotlb_hit\":%llu,"
+            "\"full_accepted\":%d}\n",
+            phase, (unsigned)pause_mode, natural_first.c_str(), g_cycle,
+            pause_request_cycle, pause_seal_cycle, pause_first_quiet_cycle,
+            pause_end_cycle,
+            (pause_request_cycle >= 0) ? (g_cycle - pause_request_cycle) : -1L,
+            s.offers, s.wlast, s.pendb,
+            s.children, (unsigned long long)s.childbytes, s.parents,
+            (unsigned long long)s.end, (unsigned long long)s.rbytes,
+            (unsigned long long)s.wbytes,
+            (int)s.held, (int)s.readbusy, (int)s.preparebusy, (int)s.quiet,
+            (unsigned long long)s.v_rbytes, (unsigned long long)s.v_wbytes,
+            (int)s.a_done,
+            (unsigned long long)n_tl_accept, (unsigned long long)n_tl_resp,
+            (unsigned long long)n_ptw_active,
+            (unsigned long long)n_iotlb_lookup,
+            (unsigned long long)n_iotlb_hit,
+            (int)full_accepted);
+    }
+#endif
+
     // Saved pre-copy payload snapshots; index 0 = V (DMA0), 1 = A (DMA1).
     std::vector<uint64_t> nat_src_saved[2];
     std::vector<uint64_t> nat_dst_saved[2];
@@ -1171,6 +1171,8 @@
         top->read_admit_mode_i =
             (read_admit_measure_only && !measurement_phase) ? 1 : read_admit_mode_val;
         top->read_budget_i     = read_budget;
         top->read_period_i     = read_period;
+        top->pause_a_i = pause_active ? 1 : 0;
+        top->pause_reads_a_i = (pause_active && pause_mode == 1) ? 1 : 0;
 #endif

         top->cfg_sel   = cfg_sel   ? 1 : 0;
@@ -1416,6 +1416,52 @@
             nat_r_stall_prev = r_stall;
         }
+
+        // ================= §42 pause/drain control (pre-edge) ==============
+        // Trigger once when the configured natural-run conditions first hold.
+        if (natural_enable && nat_hw_track && !pause_triggered) {
+            const bool both_issued = (n_nat_hw_v_issue >= 1 && n_nat_hw_a_issue >= 1);
+            if (both_issued &&
+                top->dbg_pause_a_offers >= pause_offers &&
+                top->dbg_pause_a_offers > top->dbg_pause_a_wlast &&
+                top->dbg_pause_a_end > top->dbg_pause_a_rbytes) {
+                pause_triggered = true;
+                pause_active    = true;
+                pause_request_cycle = g_cycle;
+                top->pause_a_i = 1;
+                top->pause_reads_a_i = (pause_mode == 1) ? 1 : 0;
+                top->eval();   // re-evaluate with pause inputs, no clock
+                pause_capture(pause_req_snap);
+                pause_emit("request", pause_req_snap);
+            }
+        }
+        if (pause_active) {
+            if (pause_active_cycles >= pause_window) {
+                pause_active = false;
+                top->pause_a_i = 0;
+                top->pause_reads_a_i = 0;
+                top->eval();   // re-evaluate without clock
+                pause_end_cycle = g_cycle;
+                pause_capture(pause_end_snap);
+                pause_emit("end", pause_end_snap);
+            } else {
+                ++pause_active_cycles;
+                if (top->dbg_pause_a_quiet && !pause_quiet_seen) {
+                    pause_quiet_seen = true;
+                    pause_first_quiet_cycle = g_cycle;
+                    pause_quiet_children = (uint32_t)top->dbg_pause_a_children;
+                    pause_capture(pause_quiet_snap);
+                    pause_emit("first_quiet", pause_quiet_snap);
+                }
+                if (!pause_sealed && pause_active_cycles >= 2 && !top->dbg_pause_a_held) {
+                    pause_sealed = true;
+                    pause_seal_cycle = g_cycle;
+                    pause_sealed_offers = (uint32_t)top->dbg_pause_a_offers;
+                    pause_capture(pause_seal_snap);
+                    pause_emit("sealed", pause_seal_snap);
+                }
+                if (pause_sealed &&
+                    (uint32_t)top->dbg_pause_a_offers > pause_sealed_offers) {
+                    pause_a_offers_grew_after_seal = true;
+                }
+                if (pause_quiet_seen &&
+                    (uint32_t)top->dbg_pause_a_children > pause_quiet_children) {
+                    pause_children_grew_after_quiet = true;
+                }
+            }
+        }
 #else
         const bool     s_comp_ar_v = top->comp_ar_valid;
@@ -880,6 +880,22 @@

         nat_clear_run_state();
+
+#ifdef ACTUAL_DMA_SYSTEM
+        pause_triggered = false;
+        pause_active = false;
+        pause_sealed = false;
+        pause_quiet_seen = false;
+        pause_a_offers_grew_after_seal = false;
+        pause_children_grew_after_quiet = false;
+        pause_request_cycle = -1;
+        pause_seal_cycle = -1;
+        pause_first_quiet_cycle = -1;
+        pause_end_cycle = -1;
+        pause_active_cycles = 0;
+        pause_sealed_offers = 0;
+        pause_quiet_children = 0;
+#endif
+
         setup_memory_natural();
         mem.clear();
@@ -1055,6 +1055,37 @@
         std::printf("POSTTL-STATS parents=%u children=%u policy=%u\n", (unsigned)top->dbg_frontier_grant, (unsigned)top->dbg_frontier_wait, (unsigned)read_admit_mode_val);
         nat_report_json(beats);
         nat_report_placement_json();
+
+#ifdef ACTUAL_DMA_SYSTEM
+        if (pause_mode > 0) {
+            CHECK(pause_triggered, "pause mode requested but trigger never fired");
+            CHECK(!pause_a_offers_grew_after_seal,
+                  "A offers grew after pause seal (debt frontier violated)");
+            if (pause_mode == 2) {
+                CHECK(pause_quiet_seen,
+                      "mode2 requires A quiet during the pause window");
+                CHECK(!pause_children_grew_after_quiet,
+                      "mode2: new source child admissions after quiet before resume");
+                CHECK(!pause_quiet_snap.a_done,
+                      "mode2: A job was already done at first quiet");
+            }
+            CHECK(pause_request_cycle >= 0, "pause request cycle not recorded");
+            CHECK(pause_end_cycle >= pause_request_cycle,
+                  "pause end cycle is not monotonic");
+            if (pause_sealed) {
+                CHECK(pause_seal_cycle >= pause_request_cycle,
+                      "pause seal cycle is not monotonic");
+            }
+            if (pause_quiet_seen) {
+                CHECK(pause_first_quiet_cycle >= pause_request_cycle,
+                      "pause first-quiet cycle is not monotonic");
+            }
+            pause_capture(pause_term_snap);
+            pause_emit("terminal", pause_term_snap, true);
+        }
+#endif
     }

     // Only reached after every CHECK above passed; the completed/verified
@@ -3127,6 +3127,9 @@
     uint32_t    read_budget = 256;
     uint32_t    read_period = 256;
     bool        read_admit_measure_only = false;
+    uint32_t    pause_mode = 0;
+    uint32_t    pause_offers = 4;
+    uint32_t    pause_window = 10000;
 #endif

     for (int i = 1; i < argc; ++i) {
@@ -3236,6 +3236,42 @@
             }
             read_admit_measure_only = (parsed != 0);
         }
