+        if (const char* v = val("pause-window")) {
+            char* end = nullptr;
+            const unsigned long parsed = std::strtoul(v, &end, 0);
+            if (end == v || *end != '\0' || parsed == 0 || parsed > 100000000) {
+                std::fprintf(stderr,
+                    "nonblock_actual_dma_test: invalid +pause-window='%s'\n", v);
+                return 2;
+            }
+            pause_window = (uint32_t)parsed;
+        }
 #endif

     // ---- strict validation ------------------------------------------------
@@ -3310,6 +3310,13 @@
